find src/app -name "*.ts" -type f -exec awk '
  BEGIN { in_card = 0; buffer = "" }
  /app-card/ { in_card = 1; buffer = $0; next }
  in_card && />/ { 
    buffer = buffer "\n" $0
    gsub(/\[hideHint\]/, "[disableTooltip]", buffer)
    print buffer
    in_card = 0
    buffer = ""
    next
  }
  in_card {
    buffer = buffer "\n" $0
    next
  }
  { print }
' {} > /tmp/fixed.ts && mv /tmp/fixed.ts {} \; && echo "Fixed multi-line card bindings"

